def cleanup():
    for device in output_devices:
        try:
            device.close()
        except DeviceClosedError:
            pass

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    cleanup()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def set_gpio_state(pin, state):
    if pin not in GPIO_PINS:
        raise ValueError(f"Invalid GPIO pin: {pin}")
    if state not in [True, False]:
        raise ValueError(f"Invalid state: {state}")

    try:
        output_devices[GPIO_PINS.index(pin)].value = state
        print(f"Set GPIO {pin} to {'HIGH' if state else 'LOW'}")
    except DeviceClosedError as e:
        print(f"Error setting GPIO {pin}: {e}")
        cleanup()
        sys.exit(1)

