import smbus2
import time
import sys
from signal import signal, SIGINT

# Constants
INA219_ADDRESS = 0x40
INA219_REG_CURRENT = 0x01
INA219_REG_VOLTAGE = 0x02
INA219_REG_POWER = 0x03

# SMBus setup
bus = None

def read_ina219_register(register):
    try:
        return bus.read_word_data(INA219_ADDRESS, register)
    except IOError as e:
        print(f"Error reading from INA219: {e}", file=sys.stderr)
        sys.exit(1)

def convert_voltage(raw_voltage):
    # Convert raw voltage to actual voltage
    return raw_voltage * 0.00125

def convert_current(raw_current):
    # Convert raw current to actual current
    return raw_current * 0.00125

def convert_power(raw_power):
    # Convert raw power to actual power
    return raw_power * 0.01

def check_validity(voltage, current, power):
    # Simple validity check
    if voltage < 0 or current < 0 or power < 0:
        return False
    return True

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    if bus:
        bus.close()
    sys.exit(0)

def main():
    global bus
    try:
        bus = smbus2.SMBus(1)  # Use I2C bus 1
    except IOError as e:
        print(f"Failed to open I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    signal(SIGINT, signal_handler)

    while True:
        try:
            raw_voltage = read_ina219_register(INA219_REG_VOLTAGE)
            raw_current = read_ina219_register(INA219_REG_CURRENT)
            raw_power = read_ina219_register(INA219_REG_POWER)

            voltage = convert_voltage(raw_voltage)
            current = convert_current(raw_current)
            power = convert_power(raw_power)

            if not check_validity(voltage, current, power):
                print("Invalid reading detected, skipping...", file=sys.stderr)
                continue

            print(f"Voltage: {voltage:.3f} V, Current: {current:.3f} A, Power: {power:.3f} W")

        except Exception as e:
            print(f"An error occurred: {e}", file=sys.stderr)
            sys.exit(1)

        time.sleep(2)

if __name__ == "__main__":
    main()

import time
import signal
from gpiozero import PWMOutputDevice
from gpiozero.exc import DeviceClosed, PinInvalidFunction

# List of GPIO pins to control
pins = [5, 6, 13, 17, 18, 22, 23, 24, 27]

# Dictionary to hold PWMOutputDevice instances
pwm_devices = {}

def cleanup():
    for pin, device in pwm_devices.items():
        try:
            device.close()
            print(f"Released GPIO {pin}")
        except Exception as e:
            print(f"Error releasing GPIO {pin}: {e}")

def signal_handler(sig, frame):
    print("Interrupt received, cleaning up...")
    cleanup()
    exit(0)

# Register signal handler for graceful shutdown
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

try:
    # Initialize PWM devices
    for pin in pins:
        try:
            pwm_devices[pin] = PWMOutputDevice(pin, frequency=1000)
            print(f"Initialized GPIO {pin} for PWM")
        except PinInvalidFunction as e:
            print(f"Error initializing GPIO {pin}: {e}")
            cleanup()
            exit(1)

    # Main loop
    while True:
        for pin, device in pwm_devices.items():
            try:
                # Generate a random PWM value between 0 and 1
                value = round(time.time() % 2 / 2, 2)
                device.value = value
                print(f"Set GPIO {pin} to PWM value: {value}")
            except DeviceClosed as e:
                print(f"Error setting GPIO {pin}: {e}")
                cleanup()
                exit(1)
        time.sleep(1)

except KeyboardInterrupt:
    print("Program interrupted by user")

finally:
    cleanup()

